def pow_sub(a: int, n: int = 5) -> int:
    return a ** n - a

def divisibility_census(lo: int = -6, hi: int = 12) -> None:
    for a in range(lo, hi + 1):
        v = pow_sub(a, 5)
        assert v % 5 == 0 and v % 30 == 0, f'FAILED at a={a}'
        print(f'a={a:>3}: a^5-a={v:>8}  /5={v//5:>7}  /30={v//30:>6}')
    print('All values divisible by 5 and by 30.')

if __name__ == '__main__':
    divisibility_census()

def lhs(a: int) -> int:
    return a ** 5 - a

def rhs(a: int) -> int:
    return a * (a - 1) * (a + 1) * (a ** 2 + 1)

def verify_factorisation(lo: int = -20, hi: int = 20) -> None:
    for a in range(lo, hi + 1):
        assert lhs(a) == rhs(a), f'FAILED at a={a}'
    print(f'Factorisation verified for a in [{lo}, {hi}].')

if __name__ == '__main__':
    verify_factorisation()

from math import gcd, prod
from functools import reduce

def primes_up_to(limit: int) -> list[int]:
    sieve = [True] * (limit + 1)
    sieve[0:2] = [False, False]
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, p in enumerate(sieve) if p]

def M_formula(n: int) -> int:
    return prod(p for p in primes_up_to(200) if (n - 1) % (p - 1) == 0)

def M_empirical(n: int) -> int:
    return reduce(gcd, (a ** n - a for a in range(2, 61)))

if __name__ == '__main__':
    print('gcd of a^5-a =', reduce(gcd, (a**5 - a for a in range(2, 40))))
    for n in range(2, 13):
        assert M_formula(n) == M_empirical(n)
        print(f'M({n}) = {M_formula(n)}')

